async function playTone(){try{const a=audio();await a.resume();stopTone();const o=a.createOscillator(),gain=a.createGain();o.type='sine';o.frequency.value=hz(midi);gain.gain.setValueAtTime(0,a.currentTime);gain.gain.linearRampToValueAtTime(.17,a.currentTime+.08);gain.gain.setValueAtTime(.17,a.currentTime+1.3);gain.gain.linearRampToValueAtTime(0,a.currentTime+1.6);o.connect(gain).connect(a.destination);o.start();o.stop(a.currentTime+1.65);osc=o;$('listen').textContent='お手本を再生中…';o.onended=()=>{o.disconnect();gain.disconnect();if(osc===o){osc=null;$('listen').innerHTML='<span aria-hidden="true">♫</span> お手本を聴く';}};}catch(e){showError(e.message);}}
