function cleanup(){cancelAnimationFrame(raf);if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}if(source){source.disconnect();source=null;}analyser=null;$('volume').style.width='0%';}
function finish(cancelled=false){if(!active)return;active=false;cleanup();lock(false);$('statusDot').classList.remove('on');$('status').textContent=cancelled?'練習を中断しました':'練習完了';$('start').querySelector('span').textContent='もう一度練習する';$('remaining').textContent=cancelled?'STOPPED':'COMPLETE';if(!cancelled)$('timeFill').style.width='100%';
 if(cancelled){sessionResult=null;$('resultTitle').textContent='準備ができたら、もう一度。';$('feedback').textContent='10秒間の練習を最後まで行うと、結果が表示されます。';$('accuracy').innerHTML='—<small>%</small>';$('hold').innerHTML='—<small>秒</small>';return;}
 if(voiced<2){sessionResult={status:'insufficient_voice',detectedSeconds:Number(voiced.toFixed(1))};$('resultTitle').textContent='もう少し、声を聴かせて。';$('feedback').textContent='音程を十分に検出できませんでした。静かな場所で、マイクに少し近づいて「あー」と声を出してください。';$('accuracy').innerHTML='—<small>%</small>';$('hold').innerHTML='—<small>秒</small>';return;}
 const pct=Math.round(matched/voiced*100),avg=signedError/voiced;sessionResult={status:'complete',target:note(midi),accuracyPercent:pct,longestHoldSeconds:Number(best.toFixed(1)),detectedSeconds:Number(voiced.toFixed(1)),meanAbsoluteCents:Number((totalError/voiced).toFixed(1))};$('accuracy').innerHTML=pct+'<small>%</small>';$('hold').innerHTML=best.toFixed(1)+'<small>秒</small>';$('resultTitle').textContent=pct>=80?'いいね、その高さを覚えよう。':pct>=45?'あと少しで、ぴったり。':'まずは、お手本の高さをつかもう。';let advice=pct>=80?'音程をよくキープできています。次は半音だけ高さを変えて、同じように試してみましょう。':avg>20?'お手本より高めに出る傾向があります。もう一度お手本を聴いて、少し低い声から合わせてみましょう。':avg< -20?'お手本より低めに出る傾向があります。もう一度お手本を聴いて、少し高い声に合わせてみましょう。':'音程が上下に揺れています。まずは中央の帯を2〜3秒キープすることを目指しましょう。';$('feedback').textContent=advice+'（声を検出：'+voiced.toFixed(1)+' / 10秒）';$('direction').textContent='下の結果をチェックしてみよう';}
function tick(now){if(!active)return;if(ctx.state!=='running'){showError('音声が中断されました。もう一度練習を始めてください。');finish(true);return;}if(now-lastFrame<45){raf=requestAnimationFrame(tick);return;}const elapsed=(now-started)/1000,dt=Math.min((now-lastFrame)/1000,.12);lastFrame=now;const input=new Float32Array(2048);analyser.getFloatTimeDomainData(input);const p=detectPitch(input,ctx.sampleRate);$('volume').style.width=Math.min(100,p.rms*650)+'%';let cents=null;if(p.frequency){cents=1200*Math.log2(p.frequency/hz(midi));const nearest=Math.round(69+12*Math.log2(p.frequency/440));$('voice').textContent=note(nearest);$('cents').textContent=(cents>=0?'+':'')+Math.round(cents)+' cents';const hit=Math.abs(cents)<=25;$('direction').textContent=hit?'ぴったり。そのままキープ':cents>0?'少し低くしてみよう':'少し高くしてみよう';$('direction').style.color=hit?'#d7fc70':'#bac9ac';voiced+=dt;totalError+=Math.abs(cents)*dt;signedError+=cents*dt;if(hit){matched+=dt;run+=dt;best=Math.max(best,run);}else run=0;}else{run=0;$('voice').textContent='—';$('cents').textContent='— cents';$('direction').textContent=p.rms>.008?'音程を探しています。まっすぐ「あー」':'声を出してみよう';$('direction').style.color='#a6b597';}points.push({t:Math.min(elapsed,10),c:cents});$('remaining').textContent=Math.max(0,10-elapsed).toFixed(1)+' SEC';$('timeFill').style.width=Math.min(100,elapsed*10)+'%';draw();if(elapsed>=10)finish();else raf=requestAnimationFrame(tick);}
async function start(){if(active){finish(true);return;}if(pending)return;pending=true;$('error').hidden=true;lock(true);$('start').disabled=true;$('start').querySelector('span').textContent='マイクを準備中…';stopTone();try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('マイクを使うには、Safari または Chrome でこのページを直接開いてください。');const a=audio();await a.resume();const s=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});if(document.hidden){s.getTracks().forEach(t=>t.stop());throw new Error('ページに戻ってから、もう一度始めてください。');}stream=s;await a.resume();source=a.createMediaStreamSource(s);analyser=a.createAnalyser();analyser.fftSize=2048;source.connect(analyser);points=[];voiced=matched=run=best=totalError=signedError=0;sessionResult=null;active=true;started=performance.now();lastFrame=started;$('status').textContent='声を聴いています';$('statusDot').classList.add('on');$('start').querySelector('span').textContent='練習を中止する';$('resultTitle').textContent='10秒間、そのまま。';$('feedback').textContent='中央の明るい帯に声のラインを合わせてみましょう。';$('accuracy').innerHTML='—<small>%</small>';$('hold').innerHTML='—<small>秒</small>';$('timeFill').style.width='0%';raf=requestAnimationFrame(tick);}catch(e){cleanup();active=false;lock(false);$('start').querySelector('span').textContent='マイクで練習する';$('status').textContent='マイク待機中';const messages={NotAllowedError:'マイクの使用が許可されていません。ブラウザのサイト設定でマイクを許可して、もう一度お試しください。アプリ内で開いている場合は、Safari / Chrome で直接開いてください。',NotFoundError:'マイクが見つかりません。マイクを接続して、もう一度お試しください。',NotReadableError:'マイクを使用できません。ほかの通話・録音アプリを閉じてお試しください。'};showError(messages[e.name]||e.message);}finally{pending=false;$('start').disabled=false;}}
$('up').onclick=()=>setTarget(Math.min(72,midi+1));$('down').onclick=()=>setTarget(Math.max(48,midi-1));$('pitch').oninput=e=>setTarget(Number(e.target.value));$('listen').onclick=playTone;$('start').onclick=start;window.addEventListener('resize',draw);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(active)finish(true);stopTone();}});window.addEventListener('pagehide',()=>{cleanup();stopTone();});setTarget(48);draw();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'set_practice_target',description:'練習する音程をC3〜C5に設定します。マイクや音の再生は開始しません。',inputSchema:{type:'object',properties:{midi:{type:'integer',minimum:48,maximum:72}},required:['midi'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){setTarget(input.midi);return{target:note(midi),frequency:hz(midi)};}});register({name:'get_practice_result',description:'現在の目標音と、直近の練習結果を読み取ります。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return{target:note(midi),active,result:sessionResult};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
